<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { opcApi } from '@/api/opc'

type Factory = { id:string; name:string; products:string[]; surfaces:string[]; certifications:string[]; lead_days:number; on_time_rate:number; quality_score:number; status:string; notes:string; distance:string }
const useMock = import.meta.env.VITE_USE_MOCK === 'true'
const search=ref(''); const statusFilter=ref(''); const dialog=ref(false); const detailDialog=ref(false); const editingId=ref(''); const selected=ref<Factory|null>(null)
const factories=ref<Factory[]>([
  {id:'f1',name:'安平恒泰丝网厂',products:['welded_mesh','fence_mesh'],surfaces:['hot_dip_galvanized','pvc_coated'],certifications:['ISO 9001','出口包装'],lead_days:13,on_time_rate:.96,quality_score:94,status:'ACTIVE',notes:'防护网主力工厂，可做加急。',distance:'8.4km'},
  {id:'f2',name:'河北鑫源金属网业',products:['screen_mesh','expanded_mesh'],surfaces:['none','electro_galvanized'],certifications:['材质报告','数控编织'],lead_days:16,on_time_rate:.93,quality_score:91,status:'ACTIVE',notes:'工业筛网和不锈钢网能力强。',distance:'12.7km'},
  {id:'f3',name:'安平华辰护栏厂',products:['fence_mesh','hexagonal_mesh'],surfaces:['powder_coated','pvc_coated'],certifications:['欧标包装','小批量'],lead_days:11,on_time_rate:.91,quality_score:88,status:'ACTIVE',notes:'护栏和六角网，排产灵活。',distance:'6.2km'},
])
const form=reactive({name:'',products:[] as string[],surfaces:[] as string[],certifications:'' as string,lead_days:15,on_time_rate:95,quality_score:85,status:'ACTIVE',notes:'',distance:''})
const productOptions=[['焊接网','welded_mesh'],['护栏网','fence_mesh'],['六角网','hexagonal_mesh'],['工业筛网','screen_mesh'],['钢板网','expanded_mesh']]
const surfaceOptions=[['无处理','none'],['电镀锌','electro_galvanized'],['热镀锌','hot_dip_galvanized'],['浸塑','pvc_coated'],['喷塑','powder_coated']]
const labels:Record<string,string>={welded_mesh:'焊接网',fence_mesh:'护栏网',hexagonal_mesh:'六角网',screen_mesh:'工业筛网',expanded_mesh:'钢板网',none:'无处理',electro_galvanized:'电镀锌',hot_dip_galvanized:'热镀锌',pvc_coated:'浸塑',powder_coated:'喷塑'}
const filtered=computed(()=>factories.value.filter(x=>(!search.value||`${x.name}${x.products.join('')}${x.certifications.join('')}`.toLowerCase().includes(search.value.toLowerCase()))&&(!statusFilter.value||x.status===statusFilter.value)))

onMounted(async()=>{if(useMock)return;try{const{data}=await opcApi.listFactories();factories.value=data.map((x:any)=>({...x,distance:'—'}))}catch{ElMessage.warning('工厂数据加载失败，已保留演示数据')}})
function reset(){Object.assign(form,{name:'',products:[],surfaces:[],certifications:'',lead_days:15,on_time_rate:95,quality_score:85,status:'ACTIVE',notes:'',distance:''})}
function openCreate(){editingId.value='';reset();dialog.value=true}
function openEdit(x:Factory){editingId.value=x.id;Object.assign(form,{...x,on_time_rate:Math.round(x.on_time_rate*100),certifications:x.certifications.join('、')});dialog.value=true}
function openDetail(x:Factory){selected.value=x;detailDialog.value=true}
async function save(){if(!form.name.trim()||!form.products.length)return ElMessage.warning('请填写工厂名称并选择产品能力');const payload={name:form.name,products:form.products,surfaces:form.surfaces,certifications:form.certifications.split(/[、,，]/).filter(Boolean),lead_days:form.lead_days,on_time_rate:form.on_time_rate/100,quality_score:form.quality_score,status:form.status,notes:form.notes};if(editingId.value){if(!useMock)await opcApi.updateFactory(editingId.value,payload);const x=factories.value.find(x=>x.id===editingId.value);if(x)Object.assign(x,payload,{distance:form.distance})}else{const id=useMock?`f-${Date.now()}`:(await opcApi.createFactory(payload)).data.id;factories.value.unshift({id,...payload,distance:form.distance||'—'})}dialog.value=false;ElMessage.success('工厂档案已保存')}
async function remove(x:Factory){await ElMessageBox.confirm(`确认删除“${x.name}”？`,'删除工厂',{type:'warning'});if(!useMock)await opcApi.deleteFactory(x.id);factories.value=factories.value.filter(i=>i.id!==x.id);ElMessage.success('工厂已删除')}
function toggle(x:Factory){x.status=x.status==='ACTIVE'?'PAUSED':'ACTIVE';ElMessage.success(x.status==='ACTIVE'?'工厂已启用':'工厂已停用')}
defineExpose({openCreate})
</script>

<template><div>
  <div class="stats"><span><b>{{ factories.length }}</b>合作工厂</span><span><b>{{ Math.round(factories.reduce((s,x)=>s+x.on_time_rate,0)/factories.length*100) }}%</b>平均准时率</span><span><b>{{ Math.round(factories.reduce((s,x)=>s+x.lead_days,0)/factories.length) }}天</b>平均交期</span><span><b>{{ factories.filter(x=>x.status==='PAUSED').length }}</b>暂停合作</span></div>
  <div class="toolbar"><el-input v-model="search" placeholder="搜索工厂、产品或资质" :prefix-icon="'Search'" clearable/><el-select v-model="statusFilter" placeholder="全部状态" clearable><el-option label="合作中" value="ACTIVE"/><el-option label="已停用" value="PAUSED"/></el-select><el-button type="primary" @click="openCreate"><el-icon><Plus/></el-icon>录入工厂</el-button></div>
  <div class="grid"><article v-for="x in filtered" :key="x.id" :class="['card',{paused:x.status==='PAUSED'}]"><header><i>安</i><div><h3>{{ x.name }}</h3><p>{{ x.products.map(v=>labels[v]||v).join(' · ') }}</p></div><strong>{{ x.quality_score }}<small>分</small></strong></header><div class="state"><span><i></i>{{ x.status==='ACTIVE'?'合作中':'已停用' }}</span><span>{{ x.distance }}</span></div><div class="metrics"><div><span>预计交期</span><b>{{ x.lead_days }}天</b></div><div><span>准时率</span><b>{{ Math.round(x.on_time_rate*100) }}%</b></div><div><span>工艺能力</span><b>{{ x.surfaces.length }}项</b></div></div><div class="tags"><span v-for="tag in [...x.surfaces.map(v=>labels[v]||v),...x.certifications]" :key="tag">{{ tag }}</span></div><footer><button @click="openDetail(x)">能力档案</button><button @click="openEdit(x)">编辑</button><button @click="toggle(x)">{{ x.status==='ACTIVE'?'停用':'启用' }}</button><button class="danger" @click="remove(x)">删除</button></footer></article></div>
  <el-dialog v-model="dialog" :title="editingId?'编辑合作工厂':'录入合作工厂'" width="680px"><el-form label-position="top"><div class="form-grid"><el-form-item label="工厂名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="合作状态"><el-select v-model="form.status"><el-option label="合作中" value="ACTIVE"/><el-option label="已停用" value="PAUSED"/></el-select></el-form-item><el-form-item label="产品能力" class="wide"><el-checkbox-group v-model="form.products"><el-checkbox v-for="o in productOptions" :key="o[1]" :label="o[1]">{{ o[0] }}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="表面处理" class="wide"><el-checkbox-group v-model="form.surfaces"><el-checkbox v-for="o in surfaceOptions" :key="o[1]" :label="o[1]">{{ o[0] }}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="标准交期（天）"><el-input-number v-model="form.lead_days" :min="1"/></el-form-item><el-form-item label="历史准时率（%）"><el-input-number v-model="form.on_time_rate" :min="0" :max="100"/></el-form-item><el-form-item label="质量评分"><el-input-number v-model="form.quality_score" :min="0" :max="100"/></el-form-item><el-form-item label="距离"><el-input v-model="form.distance"/></el-form-item><el-form-item label="资质与能力标签" class="wide"><el-input v-model="form.certifications" placeholder="用顿号分隔，如 ISO 9001、出口包装"/></el-form-item><el-form-item label="备注" class="wide"><el-input v-model="form.notes" type="textarea" :rows="3"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
  <el-dialog v-model="detailDialog" title="工厂能力档案" width="620px"><div v-if="selected" class="detail"><h3>{{ selected.name }}</h3><p>{{ selected.notes }}</p><dl><div><dt>产品能力</dt><dd>{{ selected.products.map(v=>labels[v]||v).join('、') }}</dd></div><div><dt>表面处理</dt><dd>{{ selected.surfaces.map(v=>labels[v]||v).join('、') }}</dd></div><div><dt>资质</dt><dd>{{ selected.certifications.join('、') }}</dd></div><div><dt>交期/准时率</dt><dd>{{ selected.lead_days }}天 / {{ Math.round(selected.on_time_rate*100) }}%</dd></div></dl></div><template #footer><el-button @click="detailDialog=false">关闭</el-button><el-button type="primary" @click="detailDialog=false;selected&&openEdit(selected)">编辑档案</el-button></template></el-dialog>
</div></template>

<style scoped>
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:14px}.stats span,.card{background:#fff;border:1px solid #e2eaf2;border-radius:12px;box-shadow:0 5px 18px rgba(23,47,79,.045)}.stats span{padding:17px;color:#8794a5;font-size:10px}.stats b{display:block;font-size:22px;color:#203249;margin-bottom:4px}.toolbar{display:flex;justify-content:flex-end;gap:8px;margin-bottom:14px}.toolbar .el-input{width:260px}.toolbar .el-select{width:120px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{padding:17px}.card.paused{opacity:.65}.card header{display:grid;grid-template-columns:40px 1fr auto;gap:9px;align-items:center}.card header>i{width:40px;height:40px;display:grid;place-items:center;border-radius:9px;background:#e9f2ff;color:#286dcc;font-style:normal;font-weight:700}.card h3{font-size:13px;margin:0}.card p{color:#909daa;font-size:9px;margin:4px 0 0}.card header>strong{color:#159877;font-size:17px}.card small{font-size:8px}.state{display:flex;justify-content:space-between;margin:14px 0 10px;font-size:8px;color:#8997a8}.state i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#23b58a;margin-right:4px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);background:#f7f9fc;border-radius:8px;padding:10px}.metrics div{text-align:center;border-right:1px solid #e2e9f1}.metrics div:last-child{border:0}.metrics span,.metrics b{display:block}.metrics span{font-size:8px;color:#8b98a8}.metrics b{font-size:11px;margin-top:4px}.tags{display:flex;gap:5px;flex-wrap:wrap;min-height:48px;padding:12px 0}.tags span{background:#eef3f8;color:#60748a;padding:4px 6px;border-radius:4px;font-size:8px}.card footer{display:flex;gap:5px;border-top:1px solid #edf1f5;padding-top:11px}.card footer button{flex:1;border:1px solid #d3dde7;background:#fff;color:#52677e;border-radius:5px;padding:6px 2px;font-size:8px;cursor:pointer}.card footer .danger{color:#d65a4d;border-color:#f1d3cf}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.form-grid .wide{grid-column:1/-1}.form-grid .el-select{width:100%}.detail p{color:#738398;font-size:11px}.detail dl{border:1px solid #e4eaf1;border-radius:8px;overflow:hidden}.detail dl div{display:grid;grid-template-columns:120px 1fr;border-bottom:1px solid #e8edf3}.detail dl div:last-child{border:0}.detail dt,.detail dd{padding:10px;margin:0;font-size:10px}.detail dt{background:#f6f8fb;color:#77879a}@media(max-width:1000px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:700px){.stats,.grid,.form-grid{grid-template-columns:1fr}.toolbar{flex-wrap:wrap}.toolbar .el-input,.toolbar .el-select{width:100%}}
</style>
